"use strict";const e=require("../common/vendor.js"),r=require("./api.js");exports.getImageUrl=function(e){return e?r.absAsset(e):""},exports.uploadImage=function(r){return new Promise((a,t)=>{e.index.uploadFile({url:"/api/upload-image",filePath:r,name:"file",success:e=>{try{const r=JSON.parse(e.data),s=r.url||r.path||"";s?a(s):t(new Error("上传返回数据无 url"))}catch(r){t(new Error("解析上传响应失败"))}},fail:e=>t(e)})})};
